(() => {'use strict';const $=id=>document.getElementById(id),g=()=>window.gameDebug;let ready=false,queue=[],current=null,timer=null,rollInterval=null,lastQuest='',seenQuest='',rewardTimer=null;const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function init(){if(ready)return;ready=true;document.body.classList.add('game-ui','illustrated-ui');const viewport=$('viewport'),shell=document.querySelector('.map-shell');viewport.append($('party'),$('target-panel'),$('initiative'));const health=document.createElement('button');health.id='hud-health';health.setAttribute('aria-label','Лист активного героя');health.onclick=()=>window.viewsDebug.switchTab('hero');viewport.append(health);const dock=document.createElement('section');dock.id='play-dock';dock.className='play-dock';dock.append($('map-hands'),document.querySelector('.turn-strip'),document.querySelector('.actions'));shell.append($('dialogue'));const roll=document.createElement('section');roll.id='roll-result';roll.hidden=true;roll.setAttribute('aria-label','Результат броска');roll.innerHTML='<div class="check-die"><span id="die-art"></span><b id="check-die"></b></div><div class="check-copy"><div class="roll-heading"><b id="check-title"></b><span id="check-dc"></span></div><p id="check-formula"></p><strong id="check-outcome" aria-live="polite"></strong></div><button id="check-next" aria-label="Закрыть результат"></button>';shell.append(roll,dock);$('die-art').innerHTML=window.UIIcons?.svg('dice')||'';$('check-next').innerHTML=window.UIIcons?.svg('close')||'×';$('check-next').onclick=()=>finish(true);$('target-toggle').onclick=()=>{const d=$('modal');$('modal-title').textContent=$('target-name').textContent;const p=document.createElement('p');p.textContent=$('target-hp').textContent+' · '+$('target-extra').textContent;$('modal-body').replaceChildren(p);d.showModal();};const history=$('journal');history.title='Хроника бросков';history.setAttribute('aria-label','Хроника бросков');history.onclick=()=>g().journal();document.querySelector('header').append(history);const notes=$('episode-status');notes.className='quest-notes';notes.setAttribute('aria-label','Заметки и задание');document.querySelector('header').append(notes);notes.onclick=openNotes;const reward=document.createElement('section');reward.id='reward-notice';reward.hidden=true;reward.setAttribute('role','status');shell.append(reward);render();}
async function finish(early=false){if(!current||$('roll-result').classList.contains('leaving'))return;if(early&&$('roll-result').classList.contains('rolling'))return;clearTimeout(timer);clearInterval(rollInterval);const job=current;$('roll-result').classList.add('leaving');await pause(g().state.settings.animations?170:0);$('roll-result').classList.remove('leaving');current=null;$('roll-result').hidden=true;$('roll-result').classList.remove('rolling');document.body.classList.remove('checking');job.resolve();g()?.render();run();}
async function run(){if(current||!queue.length)return;if($('map-view').hidden)window.viewsDebug.switchTab('map');current=queue.shift();const job=current,r=job.r,panel=$('roll-result');panel.hidden=false;document.body.classList.add('checking');panel.classList.add('rolling');$('check-title').textContent=job.title;$('check-dc').textContent=r.dc!==undefined?'СЛ '+r.dc:r.expression||('d'+(r.sides||20));$('check-formula').textContent='Бросаем '+(r.expression||'d20')+'…';$('check-outcome').textContent='';$('check-next').disabled=true;let frame=0;const sides=r.sides||20;const animate=g().state.settings.animations;rollInterval=setInterval(()=>{$('check-die').textContent=1+(frame++*7+3)%sides;},75);await pause(animate?720:20);if(current!==job)return;clearInterval(rollInterval);panel.classList.remove('rolling');$('check-next').disabled=false;$('check-die').textContent=r.natural??r.total;$('check-formula').textContent=r.dc!==undefined?(r.values||[r.natural]).join(' / ')+' '+(r.bonus>=0?'+':'−')+' '+Math.abs(r.bonus||0)+' = '+r.total:r.text||r.total;const outcome=r.outcome||(r.dc!==undefined?(r.success?'Успех':'Неудача'):'Результат '+r.total);$('check-outcome').textContent=outcome;$('check-outcome').className=r.dc!==undefined&&!r.success?'check-failure':'check-success';timer=setTimeout(finish,animate?2400:30);}
function check(r,title='Бросок',blocking=true){if(!ready)return Promise.resolve();return new Promise(resolve=>{queue.push({r,title,resolve,blocking});run();});}
function openNotes(){seenQuest=lastQuest;const d=$('modal');$('modal-title').textContent='Записки путешествия';const body=$('modal-body');body.replaceChildren();const e=g().state.episode;if(!e){const p=document.createElement('p');p.textContent='Активных заданий пока нет.';body.append(p);}else{const h=document.createElement('h3');h.textContent='Пропавший послушник';const p=document.createElement('p');p.textContent=e.stage==='done'?'Завершено. Лин вернулся, записи переданы Эллен. Награда получена: 25 монет и 40 опыта.':e.stage==='report'?'Лин вернулся в часовню. Поговорите с Эллен и передайте ей журнал.':e.unlocked?'Проход открыт. Найдите Лина в крипте.':'Найдите путь в крипту: расспросите Эллен, изучите следы или откройте дверь.';body.append(h,p);for(const clue of e.clues||[]){const p=document.createElement('p');p.className='clue-note';p.textContent=clue;body.append(p);}if(e.stage!=='done'){const b=document.createElement('button');b.textContent='Показать цель на карте';b.onclick=()=>{d.close();window.Episode.focus();};body.append(b);}}d.showModal();render();}
function reward(gold,xp){if(!ready)return;const notice=$('reward-notice');notice.replaceChildren();const icon=window.UIIcons?.node('bag');if(icon)notice.append(icon);const copy=document.createElement('div');const h=document.createElement('b');h.textContent='Награда получена';const p=document.createElement('span');p.textContent='+'+gold+' монет · +'+xp+' опыта';copy.append(h,p);notice.append(copy);notice.hidden=false;clearTimeout(rewardTimer);rewardTimer=setTimeout(()=>notice.hidden=true,4200);}
function icons(){if(!window.UIIcons)return;const fixed={'tab-map':'map','tab-hero':'hero','tab-bag':'bag',menu:'menu',journal:'book','episode-status':'book','zoom-out':'minus','zoom-in':'plus','camera-center':'center','camera-fit':'fit',potion:'potion',roll:'dice',end:'hourglass','combat-tools-toggle':'more','target-toggle':'more','dialogue-close':'close'};for(const [id,name]of Object.entries(fixed)){const el=$(id);if(!el)continue;if(['menu','journal','episode-status','zoom-out','zoom-in','camera-center','camera-fit','target-toggle','dialogue-close'].includes(id)){if(id==='journal'){el.querySelectorAll('span:not(.icon-holder)').forEach(s=>s.hidden=true);}else el.replaceChildren();}else{const old=el.querySelector(':scope > span:not(.icon-holder)');if(old)old.remove();}window.UIIcons.apply(el,name);}const label=$('action-label').textContent;const oldActionIcon=$('action').querySelector(':scope > span:not(.icon-holder)');if(oldActionIcon)oldActionIcon.remove();window.UIIcons.apply($('action'),/Говор|Поговор/.test(label)?'chat':/удар|Атака/.test(label)?'sword':/Чит|след|Осмотр/.test(label)?'book':/Откры|Перей/.test(label)?'hand':'steps');const a=g().active();$('map-hands').querySelectorAll('button').forEach((b,i)=>{const hand=a.hands[i];b.textContent=window.Torches.label(hand,a)||'Свободно';window.UIIcons.apply(b,({empty:'hand',sword:'sword',shield:'shield',torch:'torch',staff:'staff',bow:'bow'})[hand]||'hand');});}
function render(){if(!ready||!g())return;document.body.classList.toggle('map-active',!$('map-view').hidden);const a=g().active(),health=$('hud-health');if(health){health.replaceChildren();const portrait=document.createElement('div');portrait.className='portrait';portrait.append(window.Artwork.hero(a));health.append(portrait);const copy=document.createElement('span');copy.className='health-copy';const name=document.createElement('b');name.textContent=a.name;const hp=document.createElement('small');hp.textContent=a.hp+' / '+a.max;const track=document.createElement('span');track.className='hp-track';const fill=document.createElement('i');fill.style.width=Math.max(0,a.hp/a.max*100)+'%';track.append(fill);track.append(hp);copy.append(name,track);health.append(copy);}
const selected=g().selected,p=selected&&(g().props.find(p=>p.x===selected.x&&p.y===selected.y)||g().all().find(p=>p.x===selected.x&&p.y===selected.y&&p.id!==a.id));$('target-panel').hidden=!p||p.type==='chandelier'||!$('dialogue').hidden;if(p){$('target-panel').classList.remove('expanded');$('target-extra').hidden=true;}const e=g().state.episode;lastQuest=e?JSON.stringify([e.stage,e.unlocked,e.clues]):'';const notes=$('episode-status');notes.hidden=!e;notes.dataset.notice=lastQuest!==seenQuest?(e?.stage==='done'?'complete':'updated'):'';notes.onclick=openNotes;notes.title=e?.stage==='done'?'Задание завершено':'Записки и задание';document.querySelector('.roll-ledger').hidden=true;$('dice').hidden=true;icons();}
window.HUD={init,render,check,showRoll:(r,title)=>check(r,title,false),reward,openNotes,get pending(){return !!current?.blocking||queue.some(job=>job.blocking)}};
})();
